//! Help → About Ren, and on its second page the third-party notices.

use std::time::Duration;

use slint::{ComponentHandle, ModelRc, VecModel};

use super::{AboutWindow, App, NoticeBlock};
use crate::notices::{self, Block};

/// Where ren's source is.
const SOURCE: &str = "https://github.com/pprkut/ren";

/// The notices of what Ren is built from, generated by `just notices`
/// (scripts/notices.sh).
const NOTICES: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../THIRD-PARTY-NOTICES.html"
));

impl App {
    /// Opens the About window, or brings it to the front.
    pub(super) fn open_about(&self) {
        if let Some(about) = &*self.about.borrow() {
            let _ = about.show();
            return;
        }
        let about = match AboutWindow::new() {
            Ok(about) => about,
            Err(err) => {
                self.status(format!("Opening About Ren failed: {err}"));
                return;
            }
        };
        if let Some(dark) = self.forced_dark {
            about.set_forced_color_scheme(if dark {
                slint::language::ColorScheme::Dark
            } else {
                slint::language::ColorScheme::Light
            });
        }
        about.set_version(env!("CARGO_PKG_VERSION").into());
        about.set_source_url(SOURCE.into());
        let this = self.this.clone();
        about.on_open_source(move || {
            if let Some(app) = this.upgrade() {
                app.open_in_browser(SOURCE);
            }
        });
        // The notices exist only while their page is shown.
        let weak = about.as_weak();
        about.on_show_licenses(move || {
            if let Some(about) = weak.upgrade() {
                let blocks: Vec<NoticeBlock> = notices::blocks(NOTICES)
                    .into_iter()
                    .map(notice_block)
                    .collect();
                about.set_notices(ModelRc::new(VecModel::from(blocks)));
            }
        });
        let weak = about.as_weak();
        about.on_hide_licenses(move || {
            if let Some(about) = weak.upgrade() {
                about.set_notices(ModelRc::default());
            }
        });
        let this = self.this.clone();
        about.on_close_requested(move || {
            if let Some(app) = this.upgrade() {
                app.close_about();
            }
        });
        let this = self.this.clone();
        about.window().on_close_requested(move || {
            if let Some(app) = this.upgrade() {
                app.close_about();
            }
            slint::CloseRequestResponse::HideWindow
        });
        if let Err(err) = about.show() {
            eprintln!("ren: showing About Ren: {err}");
        }
        *self.about.borrow_mut() = Some(about);
    }

    /// Hides the About window, and drops it: not from its own callback.
    pub(super) fn close_about(&self) {
        if let Some(about) = &*self.about.borrow() {
            let _ = about.hide();
        }
        let this = self.this.clone();
        slint::Timer::single_shot(Duration::ZERO, move || {
            if let Some(app) = this.upgrade() {
                app.about.borrow_mut().take();
            }
        });
    }
}

fn notice_block(block: Block) -> NoticeBlock {
    let (kind, text) = match block {
        Block::Heading(text) => (0, text),
        Block::Paragraph(text) => (1, text),
        Block::Pre(text) => (2, text),
    };
    NoticeBlock {
        kind,
        text: text.into(),
    }
}
